"""v2.4 gameplay acceptance, using a dedicated offline browser profile."""
import json,time,base64,hashlib
def run(c,root,name):
 out=root/'tests/gameplay-evidence';out.mkdir(exist_ok=True)
 results=[]
 def js(s):return c.evaluate('(()=>{'+s+'})()')
 def check(label,s):
  try:results.append({'name':label,'pass':bool(c.evaluate(s))})
  except Exception as e:results.append({'name':label,'pass':False,'error':str(e)})
 def shot(label):
  data=c.call('Page.captureScreenshot',{'format':'png','captureBeyondViewport':False});(out/f'{name}-{label}.png').write_bytes(base64.b64decode(data['data']))
 def load():
  c.navigate(root/'index.html')
  for _ in range(200):
   if c.evaluate('!!window.AL?.game&&!!AL.Startup'):break
   time.sleep(.05)
 load()
 js("localStorage.clear()")
 load()
 check('First launch has Start New Game and no Continue',"AL.Startup.pending&&document.getElementById('startup-title').textContent==='Welcome to Aquarium Life'&&!!document.querySelector('[data-startup=new]')&&!document.querySelector('[data-startup=continue]')")
 check('New-game welcome does not create a saved game',"localStorage.getItem('aquarium-life-v2')===null")
 shot('first-launch')
 js("document.querySelector('[data-startup=new]').click();document.querySelector('[data-action=start][data-args*=marine]').click();AL.game.settings.speed=0;AL.UI.save();window.initialId=AL.game.selectedTank;")
 check('Start New Game routes to empty dry aquarium',"!AL.Startup.pending&&AL.game.tanks.length===1&&AL.game.tanks[0].emptyDry&&!AL.game.tanks[0].equipment.length")
 # Logic tests are read-only to the live fixture.
 try:results.extend(c.evaluate((root/'tests/gameplay_checks.js').read_text(encoding='utf-8')))
 except Exception as e:results.append({'name':'Logic checks execute','pass':False,'error':str(e)})
 js("AL.UI.save();window.savedSnapshot=localStorage.getItem('aquarium-life-v2')")
 expected=c.evaluate('JSON.parse(savedSnapshot)')
 load()
 check('Existing save gets Welcome Back and Continue',"AL.Startup.pending&&document.getElementById('startup-title').textContent==='Welcome Back to Aquarium Life'&&!!document.querySelector('[data-startup=continue]')")
 before=c.evaluate("localStorage.getItem('aquarium-life-v2')")
 js("document.querySelector('[data-startup=reset]').click()")
 check('Start Over asks for confirmation and offers export',"!!document.querySelector('[data-startup=confirm]')&&!!document.querySelector('[data-startup=cancel]')&&!!document.querySelector('[data-startup=export]')")
 check('Opening reset confirmation leaves save unchanged',"localStorage.getItem('aquarium-life-v2')==="+json.dumps(before))
 js("document.querySelector('[data-startup=cancel]').click();document.querySelector('[data-startup=continue]').click()")
 check('Continue preserves aquarium, currency, time and IDs',f"!AL.Startup.pending&&AL.game.selectedTank==={json.dumps(expected['selectedTank'])}&&AL.game.tanks.length===1&&AL.game.credits==={expected['credits']}&&AL.game.time==={expected['time']}&&AL.game.nextId==={expected['nextId']}")
 js("AL.Shell.open('journal','encyclopedia')")
 check('Encyclopedia defaults to exclusively marine fish',"[...document.querySelectorAll('[data-action=journalSpecies]')].every(n=>AL.Data.species[JSON.parse(n.dataset.args).id].water==='marine')&&document.querySelectorAll('[data-action=journalSpecies]').length>0")
 js("document.querySelector('[data-encyclopedia-category=flora]').click()")
 check('Saltwater coral category contains exactly five existing groups',"document.querySelectorAll('[data-action=journalFlora]').length===5&&!document.querySelector('[data-action=journalSpecies]')")
 js("document.querySelector('[data-encyclopedia-water=fresh]').click()")
 check('Freshwater plants show only six existing plants',"document.querySelectorAll('[data-action=journalFlora]').length===6&&[...document.querySelectorAll('[data-action=journalFlora]')].every(n=>AL.Data.flora[JSON.parse(n.dataset.args).id].water==='fresh')")
 js("document.querySelector('[data-encyclopedia-category=fish]').click()")
 check('Freshwater fish exclude all marine species',"[...document.querySelectorAll('[data-action=journalSpecies]')].every(n=>AL.Data.species[JSON.parse(n.dataset.args).id].water==='fresh')&&document.querySelectorAll('[data-action=journalSpecies]').length===9")
 js("document.querySelector('[data-encyclopedia-category=bottom]').click()")
 check('Bottom feeder categories retain existing species',"document.querySelectorAll('[data-action=journalSpecies]').length===2")
 js("document.querySelector('[data-encyclopedia-category=other]').click()")
 check('Unimplemented livestock category is honestly empty',"document.getElementById('primary-content').textContent.includes('No implemented entries')&&!document.querySelector('[data-action=journalSpecies]')")
 js("AL.Shell.close();document.getElementById('level').click()")
 check('Clickable keeper level opens existing Field Journal progress tab',"AL.Shell.active==='journal'&&AL.Shell.subtab==='keeper'&&document.getElementById('primary-content').textContent.includes('200 XP to level 2')")
 check('Keeper suggestions and rewards use real quests only',"document.getElementById('primary-content').textContent.includes('100 XP')&&document.getElementById('primary-content').textContent.includes('once')&&document.getElementById('primary-content').textContent.includes('No recent XP')")
 shot('keeper-progress')
 js("AL.Shell.open('settings');document.querySelector('[name=clockFormat]').value='12';document.querySelector('[data-form=settings]').requestSubmit();AL.game.time=945;AL.UI.updateVitals();AL.UI.save()")
 check('12-hour format updates main clock',"document.getElementById('clock').textContent.includes('3:45 PM')")
 js("AL.Shell.open('equipment','lighting')")
 check('Equipment schedules use selected clock format',"document.getElementById('primary-content').textContent.includes('6:00 AM')")
 js("AL.Shell.open('settings')")
 check('Fullscreen limits are explicit and controls exist',"document.getElementById('primary-content').textContent.includes('true OS borderless')&&document.querySelector('#display-mode option[value=borderless]')!==null")
 # CDP userGesture exercises real Fullscreen API; no substitute browser state.
 full=c.call('Runtime.evaluate',{'expression':"AL.GameplayUI.display('fullscreen').then(()=>({supported:document.fullscreenEnabled,active:!!document.fullscreenElement,status:document.getElementById('display-status').textContent}))",'awaitPromise':True,'returnByValue':True,'userGesture':True}).get('result',{}).get('value')
 results.append({'name':'Real browser fullscreen request succeeds or explains denial','pass':bool(full and (full['active'] or 'declined' in full['status'] or 'unavailable' in full['status'])),'observed':full})
 c.call('Runtime.evaluate',{'expression':"AL.GameplayUI.display('windowed')",'awaitPromise':True,'userGesture':True})
 check('Windowed exits Fullscreen API',"!document.fullscreenElement")
 c.call('Runtime.evaluate',{'expression':"AL.GameplayUI.display('borderless')",'awaitPromise':True,'userGesture':True})
 check('Borderless preference records browser equivalent',"AL.game.settings.displayMode==='borderless'&&document.getElementById('display-status').textContent.includes('Current display:')")
 c.call('Runtime.evaluate',{'expression':"document.fullscreenElement?document.exitFullscreen():null",'awaitPromise':True,'userGesture':True})
 js("AL.UI.save();AL.Shell.close()")
 load()
 check('Display and clock preferences persist without auto fullscreen',"AL.game.settings.clockFormat==='12'&&AL.game.settings.displayMode==='borderless'&&!document.fullscreenElement")
 js("document.querySelector('[data-startup=continue]').click();AL.Shell.open('settings');document.querySelector('[name=clockFormat]').value='24';document.querySelector('[data-form=settings]').requestSubmit();AL.UI.updateVitals()")
 check('24-hour format updates main clock',"document.getElementById('clock').textContent.includes('15:45')")
 js("window.originalRequest=document.documentElement.requestFullscreen;document.documentElement.requestFullscreen=()=>Promise.reject(new Error('User denied')); ")
 c.evaluate("AL.GameplayUI.display('fullscreen')")
 check('Denied fullscreen request reports failure without claiming fullscreen',"!document.fullscreenElement&&document.getElementById('display-status').textContent.includes('declined')")
 js("document.documentElement.requestFullscreen=originalRequest;AL.game.settings.displayMode='windowed';AL.UI.save()")
 shot('settings')
 js("AL.Shell.close();AL.game=AL.Core.newGame('marine',883);AL.game.settings.speed=0;AL.game.credits=100000;AL.game.xp=2000;AL.game.level=11;let t=AL.game.tanks[0];t.prepared=true;t.bacteria=t.bacteria2=1;AL.UI.render();AL.UI.save();AL.Store.open('rocks','saltwater')")
 c.call('Emulation.setDeviceMetricsOverride',{'width':1366,'height':768,'deviceScaleFactor':1,'mobile':False});time.sleep(.15)
 check('Compact store header includes destination, balance and X',"['store-title','store-destination','store-balance','store-close'].every(id=>document.getElementById(id).closest('.store-header'))&&document.querySelector('.store-header').offsetHeight<100")
 check('Product grid occupies more than half of desktop modal',"document.getElementById('store-products').clientHeight/document.getElementById('store-dialog').clientHeight>.55")
 shot('compact-store')
 js("document.querySelector('[data-product-id=\"rock:fiji:0\"] [data-store-action=details]').click();document.querySelector('[data-form=storePurchase]').requestSubmit()")
 check('Rock store purchase starts uncharged placement',"AL.UI.placing&&AL.renderer.placement.kind==='rock'&&AL.game.credits===100000")
 js("const n=document.getElementById('aquarium');window.wheel=new WheelEvent('wheel',{deltaY:-100,cancelable:true,bubbles:true});n.dispatchEvent(wheel)")
 check('Wheel over placement moves toward back and suppresses scroll',"AL.renderer.placement.z===.4&&wheel.defaultPrevented")
 js("document.getElementById('aquarium').dispatchEvent(new KeyboardEvent('keydown',{key:'PageDown',bubbles:true,cancelable:true}))")
 check('Keyboard depth alternative moves toward front',"AL.renderer.placement.z===.5")
 js("document.getElementById('aquarium').dispatchEvent(new WheelEvent('wheel',{deltaY:100,cancelable:true,bubbles:true}));document.getElementById('aquarium').dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',bubbles:true,cancelable:true}))")
 check('Rock placement saves z and stable bed support',"!AL.UI.placing&&AL.game.tanks[0].hardscape.at(-1).z===.6&&Math.abs(AL.game.tanks[0].hardscape.at(-1).y-AL.Habitat.plane(AL.game.tanks[0],.6)-.0125)<1e-8")
 js("AL.UI.beginObject('decor',{type:'lantern'});document.getElementById('aquarium').dispatchEvent(new KeyboardEvent('keydown',{key:'PageDown',bubbles:true}));document.getElementById('aquarium').dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',bubbles:true}))")
 check('Decoration depth is saved with selected aquarium',"AL.game.tanks[0].decorations.at(-1).z===.6")
 js("AL.game=AL.Core.act(AL.game,'buyEquipment',{type:'reefLight'});AL.game.tanks[0].lightIntensity=1;AL.game.tanks[0].lightHours=14;AL.UI.beginCoral('sps');let r=AL.game.tanks[0].hardscape.at(-1),e={species:'clown',strategy:'pair',parents:[]};AL.BroodView.initialize({...AL.game.tanks[0],hardscape:[r]},e);let p=AL.BroodView.position(AL.game.tanks[0],e);window.coralMount=p;const canvas=document.getElementById('aquarium'),box=canvas.getBoundingClientRect();canvas.dispatchEvent(new PointerEvent('pointermove',{clientX:box.x+p.x*box.width,clientY:box.y+p.y*box.height,bubbles:true}));")
 check('Coral cannot attach to a rock at different depth',"!AL.renderer.placement.valid")
 js("document.getElementById('aquarium').dispatchEvent(new WheelEvent('wheel',{deltaY:100,cancelable:true,bubbles:true}))")
 check('Wheel chooses matching supported coral depth',"AL.renderer.placement.z===.6&&AL.renderer.placement.valid")
 shot('coral-depth-preview')
 js("document.getElementById('aquarium').dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',bubbles:true}));AL.UI.save();AL.renderer.draw(AL.game,0)")
 check('Coral depth and attachment commit together',"!AL.UI.placing&&AL.game.tanks[0].flora.at(-1).z===.6&&AL.Habitat.validAttachment(AL.game.tanks[0],AL.game.tanks[0].flora.at(-1))")
 check('Front coral paints after its supporting rock',"AL.renderer.hitboxes.findIndex(b=>b.kind==='flora')>AL.renderer.hitboxes.findIndex(b=>b.id===AL.game.tanks[0].hardscape.at(-1).id)")
 js("AL.Store.open();window.normalWheel=new WheelEvent('wheel',{deltaY:100,bubbles:true,cancelable:true});document.getElementById('store-products').dispatchEvent(normalWheel)")
 check('Ordinary modal wheel is not intercepted',"!normalWheel.defaultPrevented")
 for w,h in [(1920,1080),(1440,900),(1366,768),(1280,720),(1024,600),(760,650),(390,844)]:
  c.call('Emulation.setDeviceMetricsOverride',{'width':w,'height':h,'deviceScaleFactor':1,'mobile':False});time.sleep(.08)
  check(f'Store fits {w}x{h} with visible close control',"(()=>{const r=document.getElementById('store-close').getBoundingClientRect();return r.top>=0&&r.bottom<=innerHeight&&r.right<=innerWidth&&document.documentElement.scrollWidth<=innerWidth&&document.documentElement.scrollHeight<=innerHeight})()")
  check(f'Products scroll internally at {w}x{h}',"getComputedStyle(document.getElementById('store-products')).overflowY==='auto'&&document.getElementById('store-products').clientHeight>80")
 js("AL.Store.close();AL.UI.save()")
 load()
 check('Reload preserves depths and supports',"AL.game.tanks[0].flora.at(-1).z===.6&&AL.game.tanks[0].hardscape.at(-1).z===.6&&AL.game.tanks[0].decorations.at(-1).z===.6&&AL.Habitat.validAttachment(AL.game.tanks[0],AL.game.tanks[0].flora.at(-1))")
 js("document.querySelector('[data-startup=continue]').click();AL.Shell.open('settings');document.querySelector('[data-action=newGameDialog]').click()")
 check('Settings reset also requires confirmation',"AL.Startup.pending&&!!document.querySelector('[data-startup=confirm]')")
 js("document.querySelector('[data-startup=cancel]').click();AL.Startup.confirm(false);localStorage.setItem('aquarium-life-v2','broken-save-v24')")
 load()
 check('Corrupt save remains protected and offers recovery',"AL.Save.locked&&AL.Startup.pending&&localStorage.getItem('aquarium-life-v2')==='broken-save-v24'&&!!document.querySelector('[data-startup=import]')&&!!document.querySelector('[data-startup=recover]')")
 js("document.querySelector('[data-startup=reset]').click();document.querySelector('[data-startup=cancel]').click()")
 check('Cancelling corrupt reset never unlocks or erases data',"AL.Save.locked&&localStorage.getItem('aquarium-life-v2')==='broken-save-v24'")
 shot('protected-save')
 js("document.querySelector('[data-startup=reset]').click();document.querySelector('[data-startup=confirm]').click();document.querySelector('[data-action=start][data-args*=marine]').click();AL.game.settings.speed=0;AL.UI.save()")
 check('Confirmed reset creates one new empty aquarium',"!AL.Startup.pending&&!AL.Save.locked&&AL.game.tanks.length===1&&AL.game.credits===3000&&AL.game.xp===0&&AL.game.tanks[0].emptyDry")
 check('Six sidebar windows retain exact order',"JSON.stringify([...document.querySelectorAll('#navigation button .nav-text')].map(n=>n.textContent))===JSON.stringify(['Aquariums','Aquarium Store','Field Journal','Equipment','VIP Store','Settings'])")
 baseline=json.loads((root/'tests/freshwater-protection-baseline.json').read_text())
 changes=[p for p,digest in baseline.items() if p!='js/simulation.js' and hashlib.sha256((root/p).read_bytes()).hexdigest()!=digest]
 results.append({'name':'All 145 protected freshwater data/art files remain byte-identical','pass':not changes,'changes':changes})
 errors=[e for e in c.events if e.get('method')=='Runtime.exceptionThrown']
 network=[e for e in c.events if e.get('method')=='Network.requestWillBeSent' and e['params']['request']['url'].startswith(('http:','https:'))]
 results.append({'name':'No browser JavaScript exceptions','pass':not errors,'errors':errors})
 results.append({'name':'Gameplay performs no HTTP/HTTPS requests','pass':not network})
 report={'browser':name,'passed':sum(r['pass'] for r in results),'failed':sum(not r['pass'] for r in results),'checks':results}
 (out/f'{name}-results.json').write_text(json.dumps(report,indent=2),encoding='utf-8')
 print(json.dumps({k:report[k] for k in ['browser','passed','failed']}),flush=True)
 for r in results:
  if not r['pass']:print('FAIL',r['name'],r.get('error',''),flush=True)
 return bool(report['failed'])
